from AlgorithmImports import *
from collections import deque
from datetime import timedelta, time


class SpyCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
            .IncludeWeeklys()
            .Strikes(-200, 200)
            .Expiration(0, 365)
        )

        self.fast_values = deque(maxlen=5)
        self.slow_values = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None
        self.last_bar_end = None

        self.current_slice = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.no_entry_today = False
        self.last_processed_date = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy.Symbol, consolidator)

    def OnData(self, slice: Slice):
        self.current_slice = slice
        today = self.Time.date()

        if self.last_processed_date != today:
            self.last_processed_date = today
            self.no_entry_today = False

        self.HandleUnexpectedEquityPosition()
        self.ProcessExpirationSafety()

        if self.held_symbol is not None and self.entry_price is not None:
            self.ProcessProfitTarget(slice)
            self.ProcessTimeStop()

        if self.held_symbol is not None:
            return

        if self.entry_ticket is not None and not self.entry_ticket.Status.IsClosed():
            return

        if self.no_entry_today:
            return

    def OnFiveMinuteBar(self, sender, bar: TradeBar):
        if bar.Symbol != self.spy.Symbol:
            return

        end = bar.EndTime
        if end.tzinfo is not None:
            end = end.replace(tzinfo=None)

        if not (time(9, 35) <= end.time() <= time(16, 0)):
            return

        if self.last_bar_end is not None:
            expected = self.last_bar_end + timedelta(minutes=5)
            if end != expected:
                self.last_bar_end = end
                return

        self.last_bar_end = end

        close = float(bar.Close)
        self.fast_values.append(close)
        self.slow_values.append(close)

        if len(self.fast_values) < 5 or len(self.slow_values) < 20:
            return

        fast = sum(list(self.fast_values)[-5:]) / 5.0
        slow = sum(self.slow_values) / 20.0

        bullish = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        if not bullish:
            return

        if not (time(9, 45) <= end.time() <= time(14, 30)):
            return

        self.TryEnterCall(close)

    def TryEnterCall(self, spy_price: float):
        if self.current_slice is None:
            return

        if self.held_symbol is not None:
            return

        if self.entry_ticket is not None and not self.entry_ticket.Status.IsClosed():
            return

        chain = self.current_slice.OptionChains.get(self.option.Symbol)
        if chain is None:
            self.Debug(f"{self.Time}: skipped entry; no option chain")
            return

        current_date = self.Time.date()
        eligible = [
            contract for contract in chain
            if contract.Expiry.date() >= current_date + timedelta(days=7)
        ]

        if not eligible:
            self.Debug(f"{self.Time}: skipped entry; no eligible expiration")
            return

        expiration = min(contract.Expiry.date() for contract in eligible)
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract for contract in eligible
            if contract.Expiry.date() == expiration
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(f"{self.Time}: skipped entry; no qualifying call")
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(f"{self.Time}: call entry submitted {selected.Symbol}")

    def ProcessProfitTarget(self, slice: Slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        contract = slice.OptionChains
        quote = None

        for chain in contract.Values:
            for item in chain:
                if item.Symbol == self.held_symbol:
                    quote = item
                    break
            if quote is not None:
                break

        if quote is None:
            return

        bid = float(quote.BidPrice)
        ask = float(quote.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.5 * self.entry_price:
            self.SubmitExit("profit target")

    def ProcessTimeStop(self):
        if self.held_symbol is None:
            return

        expiry = self.held_symbol.ID.Date.date()
        previous_day = expiry - timedelta(days=1)

        if self.Time.date() == previous_day and self.Time.time() >= time(15, 45):
            self.SubmitExit("pre-expiration time stop")

    def ProcessExpirationSafety(self):
        if self.held_symbol is None:
            return

        expiry = self.held_symbol.ID.Date.date()
        if self.Time.date() >= expiry:
            self.no_entry_today = True
            self.SubmitExit("expiration safety")

    def SubmitExit(self, reason: str):
        if self.held_symbol is None:
            return

        if self.exit_ticket is not None and not self.exit_ticket.Status.IsClosed():
            return

        if self.entry_ticket is not None and not self.entry_ticket.Status.IsClosed():
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        if self.exit_ticket is not None and not self.exit_ticket.Status.IsClosed():
            self.Transactions.CancelOrder(self.exit_ticket.OrderId)

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug(f"{self.Time}: exit submitted ({reason})")

    def HandleUnexpectedEquityPosition(self):
        holdings = self.Portfolio[self.spy.Symbol]
        if holdings.Invested:
            self.no_entry_today = True
            self.Debug(
                f"{self.Time}: unexpected exercise/assignment; "
                "liquidating SPY equity"
            )
            self.MarketOrder(self.spy.Symbol, -holdings.Quantity, tag="assignment cleanup")

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status != OrderStatus.Filled:
            return

        order = self.Transactions.GetOrderById(order_event.OrderId)
        if order is None:
            return

        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            self.held_symbol = order.Symbol
            self.entry_price = float(order_event.FillPrice)
            self.Debug(
                f"{self.Time}: entered {self.held_symbol} "
                f"at {self.entry_price}"
            )
            return

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            self.Debug(
                f"{self.Time}: exited {order.Symbol} "
                f"at {order_event.FillPrice}"
            )
            self.held_symbol = None
            self.entry_price = None
            self.exit_ticket = None
            self.entry_ticket = None

    def OnEndOfAlgorithm(self):
        if self.held_symbol is not None:
            self.Debug(f"{self.Time}: algorithm ended with an open option position")

