        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(timedelta(days=0), timedelta(days=365))
        )

        self.fast_period = 5
        self.slow_period = 20
        self.closes = []
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_start = None
        self.bucket_bars = []

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.expiration_date = None

        self.exercise_handled_dates = set()
        self.expiration_processed_dates = set()

    def OnData(self, slice: Slice):
        today = self.Time.date()
        now = self.Time.time()

        if self.Portfolio[self.spy_symbol].Quantity != 0:
            if today not in self.exercise_handled_dates:
                self.Debug(
                    f"Unexpected SPY equity position detected at {self.Time}; "
                    "liquidating immediately."
                )
                self.exercise_handled_dates.add(today)
                self.MarketOrder(
                    self.spy_symbol,
                    -self.Portfolio[self.spy_symbol].Quantity
                )

        if self.held_option is not None and self.expiration_date is not None:
            if today >= self.expiration_date:
                if today not in self.expiration_processed_dates:
                    self.Debug(
                        f"Unexpected option position at expiration processing "
                        f"on {self.Time}; liquidating."
                    )
                    self.expiration_processed_dates.add(today)
                    self._liquidate_option("expiration")
            elif (
                today == self.expiration_date - timedelta(days=1)
                and now >= time(15, 45)
            ):
                self._liquidate_option("pre-expiration time stop")

        self._evaluate_profit_target(slice)

        if self.spy_symbol not in slice.Bars:
            return

        minute_bar = slice.Bars[self.spy_symbol]
        self._process_minute_bar(minute_bar, slice)

    def _process_minute_bar(self, minute_bar: TradeBar, slice: Slice):
        local_start = minute_bar.EndTime - timedelta(minutes=1)
        local_start = local_start.replace(tzinfo=None)

        if local_start.time() < time(9, 30) or local_start.time() >= time(16, 0):
            return

        bucket_start = local_start.replace(
            minute=(local_start.minute // 5) * 5,
            second=0,
            microsecond=0
        )

        if self.bucket_start is None:
            self.bucket_start = bucket_start

        if bucket_start != self.bucket_start:
            self._finalize_bucket(slice)
            self.bucket_start = bucket_start
            self.bucket_bars = []

        self.bucket_bars.append(minute_bar)

    def _finalize_bucket(self, slice: Slice):
        if self.bucket_start is None:
            return

        bars = sorted(self.bucket_bars, key=lambda bar: bar.EndTime)

        valid = len(bars) == 5
        if valid:
            expected_start = self.bucket_start
            for bar in bars:
                actual_start = bar.EndTime - timedelta(minutes=1)
                actual_start = actual_start.replace(tzinfo=None)
                if actual_start != expected_start:
                    valid = False
                    break
                expected_start += timedelta(minutes=1)

        if not valid:
            self.bucket_bars = []
            return

        consolidated = TradeBar(
            self.spy_symbol,
            self.bucket_start,
            self.bucket_start + timedelta(minutes=5),
            bars[0].Open,
            max(bar.High for bar in bars),
            min(bar.Low for bar in bars),
            bars[-1].Close,
            sum(bar.Volume for bar in bars)
        )

        self._update_averages_and_check_signal(consolidated, slice)
        self.bucket_bars = []

    def _update_averages_and_check_signal(self, bar: TradeBar, slice: Slice):
        self.closes.append(float(bar.Close))

        if len(self.closes) < self.slow_period:
            return

        current_fast = sum(self.closes[-self.fast_period:]) / self.fast_period
        current_slow = sum(self.closes[-self.slow_period:]) / self.slow_period

        bullish_crossover = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        bar_end = bar.EndTime.time()
        if not (time(9, 45) <= bar_end <= time(14, 30)):
            return

        if bullish_crossover:
            self._attempt_entry(slice, float(bar.Close))

    def _attempt_entry(self, slice: Slice, spy_price: float):
        today = self.Time.date()

        if self.held_option is not None:
            return

        if self.entry_ticket is not None and not self._ticket_finished(self.entry_ticket):
            return

        if today in self.exercise_handled_dates:
            return

        if today in self.expiration_processed_dates:
            return

        chains = list(slice.OptionChains)
        if not chains:
            self.Debug(f"Skipped entry at {self.Time}: no option chain.")
            return

        chain = None
        for candidate in chains:
            if candidate.Key.Underlying == self.spy_symbol:
                chain = candidate
                break

        if chain is None:
            self.Debug(f"Skipped entry at {self.Time}: no SPY option chain.")
            return

        eligible_expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= today + timedelta(days=7)
        })

        if not eligible_expirations:
            self.Debug(
                f"Skipped entry at {self.Time}: no expiration at least "
                "7 calendar days away."
            )
            return

        selected_expiry = eligible_expirations[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"Skipped entry at {self.Time}: no qualifying call contract."
            )
            return

        candidates.sort(
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"Entry submitted at {self.Time}: {selected.Symbol}, "
            f"expiry {selected_expiry}, strike {selected.Strike}."
        )

    def _evaluate_profit_target(self, slice: Slice):
        if self.held_option is None or self.entry_price is None:
            return

        if self.exit_ticket is not None and not self._ticket_finished(self.exit_ticket):
            return

        symbol = self.held_option
        quote = None

        if symbol in slice.QuoteBars:
            quote = slice.QuoteBars[symbol]

        if quote is None:
            return

        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._liquidate_option("50% profit target")

    def _liquidate_option(self, reason: str):
        if self.held_option is None:
            return

        if self.exit_ticket is not None and not self._ticket_finished(self.exit_ticket):
            return

        if self.entry_ticket is not None and not self._ticket_finished(self.entry_ticket):
            return

        for ticket in self.Transactions.GetOpenOrders():
            if ticket.Symbol == self.held_option:
                self.Transactions.CancelOrder(ticket.Id)

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity != 0:
            self.exit_ticket = self.MarketOrder(
                self.held_option,
                -quantity
            )
            self.Debug(
                f"Exit submitted at {self.Time}: {self.held_option}; {reason}."
            )

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status != OrderStatus.Filled:
            return

        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            self.held_option = order_event.Symbol
            self.entry_price = float(order_event.FillPrice)
            self.expiration_date = self.Securities[
                order_event.Symbol
            ].Symbol.ID.Date.date()

            self.Debug(
                f"Entry filled at {self.Time}: {order_event.Symbol}, "
                f"price {self.entry_price:.4f}."
            )

        elif (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
        ):
            self.Debug(
                f"Exit filled at {self.Time}: {order_event.Symbol}, "
                f"price {order_event.FillPrice:.4f}."
            )
            if self.Portfolio[order_event.Symbol].Quantity == 0:
                self.held_option = None
                self.entry_price = None
                self.expiration_date = None
                self.exit_ticket = None
                self.entry_ticket = None

    def _ticket_finished(self, ticket):
        return ticket.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.PartiallyFilled
        )

    def OnEndOfAlgorithm(self):
        if self.bucket_bars:
            self._finalize_bucket(None)
